#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Fenwick {
    int n;
    vector<long long> tree;

    Fenwick(int n) : n(n), tree(n + 2, 0) {}

    void add(int i, long long delta) {
        for (; i <= n; i += i & -i) {
            tree[i] += delta;
        }
    }

    void range_add(int l, int r, long long delta) {
        if (l > r) return;
        add(l, delta);
        add(r + 1, -delta);
    }

    long long query(int i) {
        long long sum = 0;
        for (; i > 0; i -= i & -i) {
            sum += tree[i];
        }
        return sum;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    Fenwick bit_const(n + 1);
    Fenwick bit_slope(n + 1);

    for (int k = 0; k < m; ++k) {
        int type;
        cin >> type;
        if (type == 1) {
            long long i, v;
            cin >> i >> v;
            long long l = i;
            long long r = min((long long)n, i + v - 1);
            if (l <= r) {
                bit_const.range_add(l, r, v + i);
                bit_slope.range_add(l, r, -1);
            }
        } else if (type == 2) {
            long long i, v;
            cin >> i >> v;
            long long l = max(1LL, i - v + 1);
            long long r = i;
            if (l <= r) {
                bit_const.range_add(l, r, v - i);
                bit_slope.range_add(l, r, 1);
            }
        } else if (type == 3) {
            int i;
            cin >> i;
            long long c = bit_const.query(i);
            long long s = bit_slope.query(i);
            long long ans = c + (long long)i * s;
            cout << ans << "\n";
        }
    }

    return 0;
}
